import pandas as pd

df = pd.DataFrame({
    "city": ["NY", "ny", "LA", "NY", "SF", None],
    "age": [34, 29, -1, 41, 38, 52],
    "spend": [120.0, 80.5, None, 300.0, 95.0, 60.0],
})
df.info()                        # dtypes, non-null counts, memory
print(df.describe().loc[["min", "max"], "age"].tolist())   # [-1.0, 52.0]  -1 is suspicious

print(df["city"].value_counts().to_dict())   # {'NY': 2, 'ny': 1, 'LA': 1, 'SF': 1}
print(len(df["city"].value_counts(dropna=False)))   # 5 groups, one is missing
print(df["city"].str.upper().value_counts(normalize=True).round(2).to_dict())
# {'NY': 0.6, 'LA': 0.2, 'SF': 0.2}

print(df.isna().sum().to_dict())  # {'city': 1, 'age': 0, 'spend': 1}
print(df["city"].nunique())       # 4  (NaN not counted)

import pandas as pd

@pd.api.extensions.register_series_accessor("money")
class MoneyAccessor:
    def __init__(self, s: pd.Series):
        if not pd.api.types.is_numeric_dtype(s):
            raise AttributeError("money accessor needs numeric data")
        self._s = s

    def fmt(self, symbol="EUR"):
        return self._s.map(lambda v: f"{v:,.2f} {symbol}")

    def vat(self, rate=0.2):
        return (self._s * rate).round(2)

prices = pd.Series([1234.5, 99.0])
print(prices.money.fmt().tolist())   # ['1,234.50 EUR', '99.00 EUR']
print(prices.money.vat().tolist())   # [246.9, 19.8]

# Built-in extension arrays behind familiar dtypes
for s in [pd.Series([1, None], dtype="Int64"),
          pd.Series(["a", "b"], dtype="category"),
          pd.Series(pd.date_range("2024", periods=2, tz="UTC"))]:
    print(type(s.array).__name__, s.dtype)
# IntegerArray Int64 / Categorical category / DatetimeArray datetime64[ns, UTC] (us on 3.x)
print(isinstance(pd.Series([1, None], dtype="Int64").array, pd.api.extensions.ExtensionArray))   # True
